STATCLASS_ERROR_CODE STATCLASS_Gmm_Init_14_7k(HANDLE_STATCLASS_GMM hGmm) {
  STATCLASS_ERROR_CODE error = STATCLASS_NO_ERROR;

  short n, k, i;

  if (NULL == hGmm) {
    error = STATCLASS_INVALID_POINTER;
  } else {
    hGmm->nModels = N_MODELS;
    hGmm->sNorm.mu = __muNorm;
    hGmm->sNorm.stddev = __stdDevNorm;

    if (NULL == (hGmm->gmmModel = (STATCLASS_GMM_MODEL*)iisCalloc(N_MODELS, sizeof(STATCLASS_GMM_MODEL)))) {
      error = STATCLASS_MEMORY_ALLOC_ERROR;
    }
  }

  if (STATCLASS_NO_ERROR == error) {
    for (n = 0; n < N_MODELS; n++) {
      if (NULL == (hGmm->gmmModel[n].gmms = (STATCLASS_GMMS*)iisCalloc(__nGmms[n], sizeof(STATCLASS_GMMS)))) {
        error = STATCLASS_MEMORY_ALLOC_ERROR;
      }
    }
  }

  if (STATCLASS_NO_ERROR == error) {
    for (n = 0; n < N_MODELS; n++) {
      for (k = 0; k < __nGmms[n]; k++) {
        hGmm->gmmModel[n].nGmms = __nGmms[n];
        if (n == 0) {
          hGmm->gmmModel[n].gmms[k].means = __meansSpeech[k];
          hGmm->gmmModel[n].gmms[k].weights = __weightsSpeech[k];
          hGmm->gmmModel[n].gmms[k].detSigma = __detSigSpeech[k];
          for (i = 0; i < N_FEATURES; i++) {
            hGmm->gmmModel[n].gmms[k].invSigma[i] = __invSigmaSpeech[k][i];
          }
        } else if (n == 1) {
          hGmm->gmmModel[n].gmms[k].means = __meansMusic[k];
          hGmm->gmmModel[n].gmms[k].weights = __weightsMusic[k];
          hGmm->gmmModel[n].gmms[k].detSigma = __detSigMusic[k];
          for (i = 0; i < N_FEATURES; i++) {
            hGmm->gmmModel[n].gmms[k].invSigma[i] = __invSigmaMusic[k][i];
          }
        }

        hGmm->gmmModel[n].gmms[k].dimension = N_FEATURES;
      }
    }
  }

  return error;
}
